  // The id has to keep the segment structure dispatch matched on, so the one
  // thing it must never do is *rewrite* the pathname. `isCanonicalPath` rejects
  // exactly the inputs `resolveDotSegments` would rewrite rather than pass
  // through — a leading `[/\\]` run, a `\`, and a dot segment at any
  // `%25`-nesting depth — and each rewrite re-spells the request into a path the
  // router never saw:
  //   - `//private/x` misses a `use("/private/**")` guard (a literal
  //     `startsWith`, matching rou3) while a catch-all static route still
  //     matches; clamping the run to a single `/` for the lookup then serves the
  //     guarded asset unauthenticated.
  //   - `/pub/%252e%252e/private/x` is four opaque segments to `~findRoute` and
  //     to that same guard. Canonicalization decodes `%2e` (so the URL parser
  //     resolves `/pub/%2e%2e/private/x` before anything matches on it) but never
  //     `%25`, so a `%25`-nested spelling is *meant* to stay opaque; resolving
  //     those dots here walks the id back to the guarded `/private/x`.
  // Same class of hole as the `%5c` peel below, so same answer: refuse, rather
  // than serve a second, cache- and WAF-invisible spelling. Assets stay reachable
  // under their canonical spelling — the one the router sees — only.
  if (!isCanonicalPath(event.url.pathname)) {
    if (options.fallthrough) {
      return;
    }
    throw new HTTPError({ status: 404 });
  }

  // The path is canonical per the check above, so there is no traversal left to
  // resolve — the pathname *is* its own resolved form. All that remains is to
  // peel one `%25` level for the on-disk lookup (guarded: malformed `%` falls
  // back to the still-encoded pathname).
  //
  // The peel must never turn an encoded separator into a real one. `decodeURI`
  // holds back `%2f` (RFC 3986 reserved) but *not* `%5c`, which it decodes to
  // `\` — and `/private%5cx` is one opaque segment to `~findRoute` and to a
  // `use("/private/**")` guard, so a backend resolving `\` would read it as the
  // guarded `/private/x`. `decodePreservingSeparators` keeps both encoded, so the
  // id keeps the segment structure routing matched on.
  //
  // `nested: false` because this is a single decode: one `%25` level off `%252f`
  // leaves a literal `%2f`, not a separator, so filenames containing `%2f` stay
  // addressable. `decodeURI` (not `decodeURIComponent`) keeps `%23`/`%3f`
  // encoded, so a URL-composing backend cannot grow a truncating `#`/`?`.
  //
  // Re-checked rather than re-resolved: with no separator introduced there is no
  // new segment boundary, so a dot segment the peel reveals (one `%25` level off
  // `%252e`) can only be one the pathname already carried at a deeper nesting —
  // refused above. Resolving one here is precisely what would re-spell the id.
  const resolvedId = withoutTrailingSlash(event.url.pathname);
  let originalId = resolvedId;
  if (resolvedId.includes("%")) {
    try {
      const decodedId = decodePreservingSeparators(resolvedId, {
        decode: decodeURI,
        nested: false,
      });
      if (isCanonicalPath(decodedId)) {
        originalId = withoutTrailingSlash(decodedId);
      }
    } catch {
      // Malformed escape (e.g. a trailing `%`): keep the still-encoded
      // `resolvedId` already assigned to `originalId` above.
    }
  }

  const acceptEncodings = parseAcceptEncoding(
    event.req.headers.get("accept-encoding") || "",
    options.encodings,
  );

  let id = originalId;
  // The asset `id` stands for: the same path without a precompressed
  // variant's encoding extension.
  let assetId = originalId;
  let meta: StaticAssetMeta | undefined;

  const _ids = idSearchPaths(originalId, acceptEncodings, options.indexNames || ["/index.html"]);

  for (const _id of _ids) {
    const _meta = await options.getMeta(_id.id);
    if (_meta) {
      meta = _meta;
      id = _id.id;
      assetId = _id.assetId;
      break;
    }
  }

  if (!meta) {
    if (options.fallthrough) {
      return;
    }
    throw new HTTPError({ statusCode: 404 });
  }

  // The chosen variant depends on `accept-encoding` whenever encodings are
  // configured, including when the unencoded file is served. Set only once an
  // asset is found so a fallthrough does not leak it to the next handler.
  if (options.encodings && Object.keys(options.encodings).length > 0) {
    const vary = event.res.headers.get("vary") || "";
    if (!/(?:^|,)\s*(?:\*|accept-encoding)\s*(?:,|$)/i.test(vary)) {
      event.res.headers.append("vary", "accept-encoding");
    }
  }

  let mtimeDate: Date | undefined;
  if (meta.mtime) {
    mtimeDate = new Date(meta.mtime);
    // Truncate to whole seconds to match HTTP date precision, so a client
    // echoing our `last-modified` in `if-modified-since` still matches.
    mtimeDate.setMilliseconds(0);

    if (!event.res.headers.get("last-modified")) {
      event.res.headers.set("last-modified", mtimeDate.toUTCString());
    }
  }

  if (meta.etag && !event.res.headers.has("etag")) {
    event.res.headers.set("etag", meta.etag);
  }

  event.res.headers.set("accept-ranges", "bytes");

  if (isCacheMatch(event.req.headers, { etag: meta.etag, lastModified: mtimeDate })) {
    return new HTTPResponse(null, {
      status: 304,
      statusText: "Not Modified",
    });
  }

  if (!event.res.headers.get("content-type")) {
    if (meta.type) {
      event.res.headers.set("content-type", meta.type);
    } else {
      // `/app.js.gz` is still `text/javascript`: resolve the requested asset's
      // type, not the extension of its precompressed variant.
      const ext = getExtension(assetId);
      const type = ext ? (options.getType?.(ext) ?? getType(ext)) : undefined;
      if (type) {
        event.res.headers.set("content-type", type);
      }
    }
  }

  if (meta.encoding && !event.res.headers.get("content-encoding")) {
    event.res.headers.set("content-encoding", meta.encoding);
  }

  if (meta.size !== undefined && meta.size > 0 && !event.res.headers.get("content-length")) {
    event.res.headers.set("content-length", meta.size + "");
  }

  // Evaluated after the conditional 304 above, so cache validation keeps
  // precedence over Range (RFC 9110 section 13.2.2).
  const range =
    event.req.headers.has("range") && meta.size !== undefined
      ? resolveRange(event.req.headers, { size: meta.size, etag: meta.etag }, mtimeDate)
      : undefined;

  if (range === "unsatisfiable") {
    event.res.headers.set("content-range", `bytes */${meta.size}`);
    event.res.headers.set("content-length", "0");
    return new HTTPResponse(null, { status: 416, statusText: "Range Not Satisfiable" });
  }

  if (range) {
    event.res.headers.set("content-range", `bytes ${range.start}-${range.end}/${meta.size}`);
    event.res.headers.set("content-length", String(range.end - range.start + 1));
    if (event.req.method === "HEAD") {
      return new HTTPResponse(null, { status: 206, statusText: "Partial Content" });
    }
    const contents = await options.getContents(id);
    if (contents === null || contents === undefined) {
      // Headers are already set, so falling through would leak them to the next handler.
      throw new HTTPError({ status: 404 });
    }
    return new HTTPResponse(await sliceBody(contents, range.start, range.end + 1), {
      status: 206,
      statusText: "Partial Content",
    });
  }

  if (event.req.method === "HEAD") {
    return new HTTPResponse(null, { status: 200 });
  }

  const contents = await options.getContents(id);
  return new HTTPResponse(contents || null, { status: 200 });
}

// --- Internal Utils ---

// `qvalue` grammar (RFC 9110 section 12.4.2).
const WEIGHT_RE = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/;

/**
 * Resolve the configured encoding extensions a request accepts, most preferred first.
 *
 * Coding names are case-insensitive, `q=0` means "not acceptable", `*` matches
 * any coding not listed explicitly and equal weights keep header order, with
 * explicitly listed codings ahead of `*` matches (RFC 9110 section 12.5.3).
 */
function parseAcceptEncoding(header?: string, encodingMap?: Record<string, string>): string[] {
  if (!encodingMap || !header) {
    return [];
  }
  const extensions = new Map<string, string>();
  for (const [name, ext] of Object.entries(encodingMap)) {
    extensions.set(normalizeCoding(name), ext);
  }
  // Coding -> weight, in header order. The first occurrence of a coding wins.
  const weights = new Map<string, number>();
  let wildcard: number | undefined;
  for (const part of header.split(",")) {
    const [rawName = "", ...params] = part.split(";");
    const name = normalizeCoding(rawName);
    if (name !== "*" && !extensions.has(name)) {
      continue;
    }
    const qParam = params.find((p) => /^\s*q\s*=/i.test(p));
    const qValue = qParam?.slice(qParam.indexOf("=") + 1).trim();
    // An unparsable weight drops the coding: identity is always a safe fallback,
    // while guessing `1` could force a coding the client tried to refuse.
    const q = qValue === undefined ? 1 : WEIGHT_RE.test(qValue) ? Number(qValue) : 0;
    if (name === "*") {
      wildcard ??= q;
    } else if (!weights.has(name)) {
      weights.set(name, q);
    }
  }
  if (wildcard) {
    for (const name of extensions.keys()) {
      if (!weights.has(name)) {
        weights.set(name, wildcard);
      }
    }
  }
  const accepted = [...weights]
    .filter(([, q]) => q > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([name]) => extensions.get(name)!);
  return [...new Set(accepted)];
}

/** Lowercase a coding name and resolve the `x-gzip` / `x-compress` aliases (RFC 9110 section 8.4.1). */
function normalizeCoding(name: string): string {
  const coding = name.trim().toLowerCase();
  return coding === "x-gzip" || coding === "x-compress" ? coding.slice(2) : coding;
}

function idSearchPaths(id: string, encodings: string[], indexNames: string[]) {
  const ids: { id: string; assetId: string }[] = [];

  for (const suffix of ["", ...indexNames]) {
    const assetId = `${id}${suffix}`;
    for (const encoding of [...encodings, ""]) {
      ids.push({ id: `${assetId}${encoding}`, assetId });
    }
  }

  return ids;
}

/** Inclusive byte range, both ends resolved against the asset size. */
type ByteRange = { start: number; end: number };

/**
 * Decide how to answer a `Range` header for an asset of known size.
 *
 * Only a single `bytes` range is honoured (RFC 9110 section 14.1.1). A malformed,
 * other-unit or multi-range header is ignored, which returns `undefined` and
 * answers with the full asset. `"unsatisfiable"` is only for a syntactically valid
 * range that cannot be served, such as one starting past the end. An `If-Range`
 * that does not match also returns `undefined` (RFC 9110 section 13.1.5).
 */
function resolveRange(
  headers: Headers,
  meta: { size: number; etag?: string },
  mtime?: Date,
): ByteRange | "unsatisfiable" | undefined {
  const ifRange = headers.get("if-range");
  if (ifRange !== null && !ifRangeMatches(ifRange, meta, mtime)) {
    return undefined;
  }

  const match = /^bytes=(\d*)-(\d*)$/i.exec(headers.get("range") || "");
  if (!match || (match[1] === "" && match[2] === "")) {
    return undefined;
  }
  const [, first = "", last = ""] = match;
  if (first !== "" && last !== "" && Number(last) < Number(first)) {
    return undefined;
  }

  const { size } = meta;
  if (first === "") {
    // Suffix form: the last `n` bytes, or the whole asset when `n` is larger.
    const length = Number(last);
    if (length === 0 || size === 0) {
      return "unsatisfiable";
    }
    return { start: Math.max(size - length, 0), end: size - 1 };
  }

  const start = Number(first);
  if (start >= size) {
    return "unsatisfiable";
  }
  const end = last === "" ? size - 1 : Math.min(Number(last), size - 1);
  return { start, end };
}

/**
 * Whether an `If-Range` validator matches the current asset. A strong ETag must
 * equal `meta.etag` byte for byte, and a date must equal `mtime`, which is already
 * truncated to whole seconds. Weak ETags never match.
 */
function ifRangeMatches(value: string, meta: { etag?: string }, mtime?: Date): boolean {
  if (value.startsWith('"') || value.startsWith("W/")) {
    return !value.startsWith("W/") && value === meta.etag;
  }
  return mtime !== undefined && new Date(value).getTime() === mtime.getTime();
}

/**
 * Slice a body to the bytes `[start, end)`. Offsets count bytes, not UTF-16
 * units, so a multibyte string is encoded before it is cut.
 */
async function sliceBody(body: BodyInit, start: number, end: number): Promise<BodyInit> {
  if (typeof body === "string") {
    return new TextEncoder().encode(body).subarray(start, end);
  }
  if (body instanceof ArrayBuffer) {
    return body.slice(start, end);
  }
  if (ArrayBuffer.isView(body)) {
    return new Uint8Array(body.buffer, body.byteOffset + start, end - start);
  }
  if (body instanceof Blob) {
    return body.slice(start, end);
  }
  // Streams and other body types are read into memory, then sliced.
  return (await new Response(body).blob()).slice(start, end);
}
